"""Print a compact view of selected Public API operations (spike tooling, not committed)."""

import json
import sys

doc = json.load(open(sys.argv[1], encoding="utf-8"))
wanted = sys.argv[2:]
schemas = doc["components"]["schemas"]


def deref(node, depth=0, seen=()):
    if depth > 7:
        return "…"
    if isinstance(node, dict):
        if "$ref" in node:
            name = node["$ref"].rsplit("/", 1)[1]
            if name in seen:
                return f"<{name}>"
            return {f"<{name}>": deref(schemas[name], depth + 1, (*seen, name))}
        out = {}
        for k, v in node.items():
            if k in ("description", "examples", "example", "title", "x-neatlogs-description"):
                continue
            out[k] = deref(v, depth + 1, seen)
        return out
    if isinstance(node, list):
        return [deref(v, depth + 1, seen) for v in node]
    return node


for path, item in doc["paths"].items():
    for method, op in item.items():
        if method not in ("get", "post", "put", "patch", "delete"):
            continue
        key = f"{method.upper()} {path}"
        if not any(w in key for w in wanted):
            continue
        print("=" * 100)
        print(key, "|", op.get("operationId"))
        print("security:", [list(s) for s in op.get("security", [])])
        print("gate:", op.get("x-neatlogs-operation-gate"), "| scopes:", op.get("x-neatlogs-scopes", ""))
        for p in op.get("parameters", []):
            p = deref(p)
            if isinstance(p, dict) and len(p) == 1 and next(iter(p)).startswith("<"):
                p = next(iter(p.values()))
            print("  param", p.get("in"), p.get("name"), p.get("required"), json.dumps(p.get("schema"))[:200])
        body = op.get("requestBody")
        if body:
            content = body.get("content", {})
            for ct, spec in content.items():
                print("  body", ct, json.dumps(deref(spec.get("schema")))[:3000])
        for status, resp in op.get("responses", {}).items():
            if not status.startswith("2"):
                continue
            resp = deref(resp)
            if isinstance(resp, dict) and len(resp) == 1 and next(iter(resp)).startswith("<"):
                resp = next(iter(resp.values()))
            for ct, spec in (resp.get("content") or {}).items():
                print("  resp", status, ct, json.dumps(spec.get("schema"))[:4000])
            if resp.get("headers"):
                print("  resp-headers", list(resp["headers"]))

